def process(fresh_water_data):
    df = fresh_water_data.copy()
    df['Exceedance'] = (df['Violation'] == 'YES').astype(int)
    result = df.groupby(['Beach Name', 'Year']).agg({
        'Exceedance': 'sum',
        'Violation': 'count'
    }).reset_index()
    result.columns = ['Beach Name', 'Year', 'Violations', 'Total_Samples']
    result['Exceedance_Rate'] = result['Violations'] / result['Total_Samples']
    return result

